  'home.why1Body': 'विश्वास, पारदर्शकता आणि सुरक्षित व्यवहार सुनिश्चित करण्यासाठी प्रत्येक शेतकरी, जमीन मालक, उपकरण प्रदाता, खरेदीदार आणि सेवा भागीदार सत्यापित आहे.',
  'home.why2Title': 'वेळ वाचवा',
  'home.why2Body': 'दिवस ऑफलाइन शोध न घालवता कृषी सेवा, यंत्रसामग्री, मजूर आणि खरेदीदार लवकर शोधा.',
  'home.why3Title': 'खर्च कमी करा',
  'home.why3Body': 'किफायतशीर निर्णय घेण्यासाठी सेवा, उपकरण भाडे आणि कृषी उपायांची तुलना करा.',
  'home.why4Title': 'प्रत्येकासाठी एकच व्यासपीठ',
  'home.why4Body': 'जमीन भाडेतत्त्व, उपकरण भाडे, मजूर सेवा, उत्पादन व्यापार आणि भविष्यातील कृषी सेवा एकाच केंद्रीकृत व्यासपीठावरून मिळवा.',
  'home.why5Title': 'प्रत्येक शेतकऱ्यासाठी बनवलेले',
  'home.why5Body': 'तुमच्याकडे 2 एकर किंवा 200 एकर असो, कृषी संगम स्केलेबल डिजिटल उपायांसह प्रत्येक आकाराच्या शेताला आधार देण्यासाठी तयार केलेले आहे.',
  'home.why6Title': 'वापरण्यास सोपे',
  'home.why6Body': 'साधे नेव्हिगेशन, स्वच्छ इंटरफेस आणि मोबाइल-फ्रेंडली डिझाइन व्यासपीठ वेगवेगळ्या डिजिटल अनुभव असलेल्या शेतकऱ्यांसाठी सुलभ बनवते.',
