  'home.cs1Body': 'విశ్వసనీయ సరఫరాదారుల నుండి ధృవీకరించబడిన విత్తనాలు, ఎరువులు, పురుగుమందులు మరియు ఇతర అవసరమైన వ్యవసాయ సామాగ్రిని అందించండి.',
  'home.cs2Title': 'పంటల కొనుగోలు-విక్రయ మార్కెట్ప్లేస్',
  'home.cs2Body': 'మెరుగైన ధరలు మరియు విస్తృత మార్కెట్ ప్రాప్యత కోసం రైతులు మరియు కొనుగోలుదారులు నేరుగా కనెక్ట్ అయ్యే పారదర్శక మార్కెట్ప్లేస్.',
  'home.cs3Title': 'నిల్వ మరియు కోల్డ్ చైన్ లాజిస్టిక్స్',
  'home.cs3Body': 'పంట కోత తర్వాత నష్టాలను తగ్గించడానికి గోదాములు, కోల్డ్ స్టోరేజ్ మరియు రవాణా సేవలను కనుగొనండి.',
  'home.cs4Title': 'ఆర్థిక సహాయం, రుణాలు మరియు బీమా',
  'home.cs4Body': 'ఆర్థిక సహాయం మరియు పంట రక్షణ కోసం బ్యాంకులు, NBFCలు, బీమా ప్రదాతలు మరియు ప్రభుత్వ పథకాలతో కనెక్ట్ అవ్వండి.',
  'home.cs5Title': 'నిపుణుల వ్యవసాయ సలహా',
  'home.cs5Body': 'పంట ప్రణాళిక, వ్యాధి నిర్వహణ, నీటిపారుదల, ఎరువులు మరియు ఆధునిక వ్యవసాయ పద్ధతులపై వ్యవసాయ నిపుణుల నుండి మార్గదర్శనం పొందండి.',
  'home.whyTitle': 'రైతులు ఎందుకు కృషి సంగంను ఎంచుకుంటారు',
  'home.why1Title': 'ధృవీకరించబడిన నెట్వర్క్',
  'home.why1Body': 'విశ్వాసం, పారదర్శకత మరియు సురక్షిత లావాదేవీలను నిర్ధారించడానికి ప్రతి రైతు, భూయజమాని, పరికరాల ప్రదాత, కొనుగోలుదారు మరియు సేవా భాగస్వామి ధృవీకరించబడతారు.',
  'home.why2Title': 'సమయం ఆదా చేయండి',
  'home.why2Body': 'రోజుల తరబడి ఆఫ్లైన్లో శోధించకుండా వ్యవసాయ సేవలు, యంత్రాలు, కూలీలు మరియు కొనుగోలుదారులను త్వరగా కనుగొనండి.',
  'home.why3Title': 'ఖర్చులను తగ్గించండి',
  'home.why3Body': 'తక్కువ ఖర్చుతో కూడిన నిర్ణయాలు తీసుకోవడానికి సేవలు, పరికరాల అద్దెలు మరియు వ్యవసాయ పరిష్కారాలను పోల్చండి.',
  'home.why4Title': 'ప్రతిదానికీ ఒకే వేదిక',
  'home.why4Body': 'భూమి లీజు, పరికరాల అద్దెలు, కూలీ సేవలు, పంట వ్యాపారం మరియు భవిష్యత్తు వ్యవసాయ సేవలను ఒకే కేంద్రీకృత వేదిక నుండి పొందండి.',
  'home.why5Title': 'ప్రతి రైతు కోసం నిర్మించబడింది',
  'home.why5Body': 'మీకు 2 ఎకరాలు లేదా 200 ఎకరాలు ఉన్నా, కృషి సంగం స్కేలబుల్ డిజిటల్ పరిష్కారాలతో ప్రతి పరిమాణపు పొలాలకు మద్దతు ఇవ్వడానికి రూపొందించబడింది.',
  'home.why6Title': 'ఉపయోగించడం సులభం',
  'home.why6Body': 'సరళమైన నావిగేషన్, శుభ్రమైన ఇంటర్ఫేస్ మరియు మొబైల్-అనుకూల డిజైన్ వివిధ స్థాయిల డిజిటల్ అనుభవం ఉన్న రైతులకు వేదికను అందుబాటులో ఉంచుతాయి.',
  'services.title': 'మా సేవలు',
  'services.subtitle': 'మీ పొలాన్ని శక్తివంతం చేయడానికి కృషి సంగం అందించే ప్రతిదీ — భూమి లీజు మరియు పరికరాల అద్దె నుండి కూలీ సేవలు మరియు పారదర్శక పంట మార్కెట్ప్లేస్ వరకు.',
  'services.land': 'భూమి లీజు',
  'services.landBody': 'సురక్షితమైన, పారదర్శక వేదిక ద్వారా ధృవీకరించబడిన భూయజమానులు మరియు రైతులతో వ్యవసాయ భూమిని లీజుకు తీసుకోండి లేదా జాబితా చేయండి.',
  'services.equipment': 'పరికరాల అద్దె',
  'services.equipmentBody': 'ధృవీకరించబడిన పరికరాల యజమానుల నుండి ట్రాక్టర్లు, హార్వెస్టర్లు, రోటావేటర్లు, సీడ్ డ్రిల్స్, స్ప్రేయర్లు మరియు ఇతర అవసరమైన వ్యవసాయ యంత్రాలను పొందండి.',
  'services.labour': 'కూలీ మరియు వ్యవసాయ సేవలు',
  'services.labourBody': 'విత్తడం, కోత, పిచికారి, నీటిపారుదల మరియు మరిన్నింటి కోసం విశ్వసనీయ వ్యవసాయ కూలీలు మరియు సేవా ప్రదాతలను కనుగొనండి.',
  'services.produce': 'పంట మార్కెట్ప్లేస్',
  'services.produceBody': 'మీ పంటలను ప్రదర్శించండి మరియు ధృవీకరించబడిన కొనుగోలుదారులతో కనెక్ట్ అయ్యి పోటీ ఆఫర్లు మరియు మెరుగైన ధరలను పొందండి.',
  'services.cta': 'ప్రారంభించండి',
  'contact.title': 'మమ్మల్ని సంప్రదించండి',
  'contact.subtitle': 'మీ నుండి వినడానికి మేము సంతోషిస్తాము. మద్దతు, భాగస్వామ్యాలు లేదా కృషి సంగం గురించి ఏవైనా ప్రశ్నలకు సంప్రదించండి.',
