  'auth.optional': 'ఐచ్ఛికం',
  'home.hero.title': 'రైతులు, కొనుగోలుదారులు మరియు వ్యవసాయ సేవల కోసం భారతదేశ డిజిటల్ వంతెన',
  'home.hero.subtitle': 'కృషి సంగం రైతులను ధృవీకరించిన కొనుగోలుదారులు, వ్యవసాయ పరికరాలు, వ్యవసాయ సేవలు, నిల్వ పరిష్కారాలు, ఆర్థిక సహాయం మరియు నిపుణుల మార్గదర్శకత్వంతో కలుపుతుంది.',
  'home.getStarted': 'ప్రారంభించండి',
  'home.exploreServices': 'సేవలను అన్వేషించండి',
  'home.whatIsTitle': 'కృషి సంగం అంటే ఏమిటి?',
  'home.agriSimple': 'వ్యవసాయం సులభం.',
  'home.whatIsBody': 'కృషి సంగం అనేది రైతులను విశ్వసనీయ భూమి లీజు, పరికరాలు మరియు సేవలతో కలిపే డిజిటల్ వేదిక.',
  'home.offerTitle': 'ఈరోజు మేము అందించేది',
  'home.landLeasing': 'భూమి లీజు',
  'home.landLeasingBody': 'పారదర్శకతతో వ్యవసాయ భూమిని లీజుకు ఇవ్వడానికి భూమి యజమానులు మరియు రైతులను సురక్షిత వేదికపై కలపండి.',
  'home.equipmentRental': 'పరికరాల అద్దె',
  'home.equipmentRentalBody': 'ధృవీకరించిన యజమానుల నుండి ట్రాక్టర్లు, హార్వెస్టర్లు, రోటావేటర్లు, సీడ్ డ్రిల్స్ మరియు ఇతర అవసరమైన వ్యవసాయ యంత్రాలను పొందండి.',
  'home.labourServices': 'వ్యవసాయ కూలీలు మరియు వ్యవసాయ సేవలు',
  'home.labourServicesBody': 'విత్తడం, కోత, పిచికారి, నీటిపారుదల మొదలైన వాటికి విశ్వసనీయ వ్యవసాయ కూలీలు మరియు సేవా ప్రదాతలను ఒకే చోట కనుగొనండి.',
  'home.comingSoon': 'త్వరలో',
  'home.comingSoonBody': 'కృషి సంగం భారతదేశ సంపూర్ణ వ్యవసాయ పర్యావరణ వ్యవస్థగా నిరంతరం విస్తరిస్తోంది. రాబోయే సేవలు:',
  'home.coming.seeds': 'విత్తనాలు, ఎరువులు మరియు వ్యవసాయ ఇన్‌పుట్‌లు',
