  'home.whyChoose': 'రైతులు కృషి సంగంను ఎందుకు ఎంచుకుంటారు',
  'home.verified': 'ధృవీకరించిన నెట్‌వర్క్',
  'home.verifiedBody': 'ఎక్కువ విశ్వాసం మరియు పారదర్శకత కోసం ప్రతి సేవా ప్రదాత ధృవీకరణకు లోనవుతారు.',
  'home.saveTime': 'సమయం ఆదా చేయండి',
  'home.saveTimeBody': 'యంత్రాలు, కూలీలు మరియు వ్యవసాయ సేవల కోసం వెతకడంలో పెట్టే శ్రమను తగ్గించండి.',
