  'about.title': 'எங்களை பற்றி',
  'about.subtitle': 'கிருஷி சங்கம்வின் பின்னணியில் உள்ள பார்வை, நோக்கம் மற்றும் மக்களைக் கண்டறியுங்கள்.',
