  'home.aboutP1': 'કૃષિ સંગમ એક વ્યાપક ડિજિટલ કૃષિ પ્લેટફોર્મ છે જે ખેતી ઇકોસિસ્ટમના દરેક ભાગને એક વિશ્વસનીય પ્લેટફોર્મ દ્વારા જોડવા માટે ડિઝાઇન કરવામાં આવ્યું છે. અમે ખેડૂતો, જમીન માલિકો, સાધન પ્રદાતાઓ, કૃષિ મજૂરો, સેવા પ્રદાતાઓ અને પાક ખરીદદારોને એકસાથે લાવીએ છીએ, જેથી બિનજરૂરી વિલંબ અથવા મધ્યસ્થીઓ વિના આવશ્યક કૃષિ સંસાધનો મેળવવાનું સરળ બને.',
