  'home.why3Body': 'ખર્ચ-અસરકારક નિર્ણયો લેવા સેવાઓ, સાધનોના ભાડા અને કૃષિ ઉકેલોની તુલના કરો.',
  'home.why4Title': 'બધું એક જ પ્લેટફોર્મ પર',
  'home.why4Body': 'જમીન લીઝ, સાધન ભાડા, મજૂર સેવાઓ, પાક વેપાર અને ભાવિ કૃષિ સેવાઓ એક જ કેન્દ્રિય પ્લેટફોર્મ પરથી મેળવો.',
  'home.why5Title': 'દરેક ખેડૂત માટે બનાવેલું',
  'home.why5Body': 'તમારી પાસે 2 એકર કે 200 એકર હોય, કૃષિ સંગમ સ્કેલેબલ ડિજિટલ ઉકેલો સાથે દરેક કદના ખેતરને ટેકો આપવા માટે બનાવવામાં આવ્યું છે.',
  'home.why6Title': 'વાપરવા સરળ',
  'home.why6Body': 'સરળ નેવિગેશન, સ્વચ્છ ઇન્ટરફેસ અને મોબાઇલ-ફ્રેન્ડલી ડિઝાઇન પ્લેટફોર્મને અલગ-અલગ ડિજિટલ અનુભવ ધરાવતા ખેડૂતો માટે સુલભ બનાવે છે.',
  'services.title': 'અમારી સેવાઓ',
  'services.subtitle': 'તમારા ખેતરને સશક્ત બનાવવા કૃષિ સંગમની દરેક વસ્તુ — જમીન લીઝ અને સાધન ભાડાથી મજૂર સેવાઓ અને પારદર્શક પાક બજાર સુધી.',
  'services.land': 'જમીન લીઝ',
  'services.landBody': 'સુરક્ષિત, પારદર્શક પ્લેટફોર્મ દ્વારા ચકાસાયેલ જમીન માલિકો અને ખેડૂતો સાથે કૃષિ જમીન લીઝ પર લો અથવા યાદી કરો.',
  'services.equipment': 'સાધન ભાડા',
  'services.equipmentBody': 'ચકાસાયેલ સાધન માલિકો પાસેથી ટ્રેક્ટર, હાર્વેસ્ટર, રોટાવેટર, સીડ ડ્રિલ, સ્પ્રેયર અને અન્ય આવશ્યક ખેતી મશીનરી મેળવો.',
  'services.labour': 'મજૂર અને કૃષિ સેવાઓ',
  'services.labourBody': 'વાવણી, લણણી, છંટકાવ, સિંચાઈ વગેરે માટે વિશ્વસનીય કૃષિ મજૂરો અને સેવા પ્રદાતાઓ શોધો.',
