  'home.sellTitle': 'നിങ്ങളുടെ വിള വിൽക്കുക',
  'home.sellBody': 'പരിശോധിച്ച വാങ്ങുന്നവരുമായി നേരിട്ട് ബന്ധപ്പെടുകയും പ്രാദേശിക മണ്ടികൾക്കപ്പുറം നിങ്ങളുടെ വിപണി വികസിപ്പിക്കുകയും ചെയ്യുക. കർഷകരെ അവരുടെ വിളകൾ പ്രദർശിപ്പിക്കാനും മത്സരാധിഷ്ഠിത ഓഫറുകൾ സ്വീകരിക്കാനും മികച്ച വിലകൾക്ക് ചർച്ച ചെയ്യാനും കൂടുതൽ സുതാര്യതയോടെ വിൽക്കാനും കൃഷി സംഗമം പ്രാപ്തരാക്കുന്നു. മധ്യസ്ഥരെ ആശ്രയിക്കുന്നത് കുറച്ചുകൊണ്ട് കർഷകരുടെ ലാഭം പരമാവധിയാക്കാൻ ഞങ്ങളുടെ പ്ലാറ്റ്ഫോം സഹായിക്കുന്നു.',
