  'home.why1Body': 'വിശ്വാസവും സുതാര്യതയും സുരക്ഷിത ഇടപാടുകളും ഉറപ്പാക്കാൻ ഓരോ കർഷകനും ഭൂവുടമയും ഉപകരണ ദാതാവും വാങ്ങുന്നയാളും സേവന പങ്കാളിയും പരിശോധിക്കപ്പെടുന്നു.',
  'home.why2Title': 'സമയം ലാഭിക്കുക',
  'home.why2Body': 'ദിവസങ്ങളോളം ഓഫ്ലൈനിൽ തിരയാതെ കാർഷിക സേവനങ്ങൾ, യന്ത്രങ്ങൾ, തൊഴിലാളികൾ, വാങ്ങുന്നവർ എന്നിവയെ വേഗത്തിൽ കണ്ടെത്തുക.',
  'home.why3Title': 'ചെലവ് കുറയ്ക്കുക',
  'home.why3Body': 'ചെലവ് കുറഞ്ഞ തീരുമാനങ്ങൾ എടുക്കുന്നതിന് സേവനങ്ങൾ, ഉപകരണ വാടകകൾ, കാർഷിക പരിഹാരങ്ങൾ എന്നിവ താരതമ്യം ചെയ്യുക.',
  'home.why4Title': 'എല്ലാത്തിനും ഒരു പ്ലാറ്റ്ഫോം',
  'home.why4Body': 'ഭൂമി പാട്ടം, ഉപകരണ വാടകകൾ, തൊഴിലാളി സേവനങ്ങൾ, വിള വ്യാപാരം, ഭാവിയിലെ കാർഷിക സേവനങ്ങൾ എന്നിവ ഒരു കേന്ദ്രീകൃത പ്ലാറ്റ്ഫോമിൽ നിന്ന് ആക്സസ് ചെയ്യുക.',
  'home.why5Title': 'എല്ലാ കർഷകർക്കും വേണ്ടി നിർമ്മിച്ചത്',
  'home.why5Body': 'നിങ്ങൾക്ക് 2 ഏക്കറോ 200 ഏക്കറോ ഉണ്ടെങ്കിലും, സ്കെയിലബിൾ ഡിജിറ്റൽ പരിഹാരങ്ങൾ ഉപയോഗിച്ച് എല്ലാ വലുപ്പത്തിലുമുള്ള കൃഷിയിടങ്ങളെ പിന്തുണയ്ക്കുന്നതിനാണ് കൃഷി സംഗമം രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്.',
  'home.why6Title': 'ഉപയോഗിക്കാൻ എളുപ്പം',
  'home.why6Body': 'ലളിതമായ നാവിഗേഷനും വൃത്തിയുള്ള ഇന്റർഫേസും മൊബൈൽ-ഫ്രണ്ട്ലി ഡിസൈനും പ്ലാറ്റ്ഫോം വിവിധ തലത്തിലുള്ള ഡിജിറ്റൽ പരിചയമുള്ള കർഷകർക്ക് പ്രാപ്യമാക്കുന്നു.',
  'services.title': 'ഞങ്ങളുടെ സേവനങ്ങൾ',
  'services.subtitle': 'നിങ്ങളുടെ കൃഷിയിടം ശാക്തീകരിക്കാൻ കൃഷി സംഗമം വാഗ്ദാനം ചെയ്യുന്നതെല്ലാം — ഭൂമി പാട്ടവും ഉപകരണ വാടകയും മുതൽ തൊഴിലാളി സേവനങ്ങളും സുതാര്യമായ വിള വിപണിയും വരെ.',
  'services.land': 'ഭൂമി പാട്ടം',
  'services.landBody': 'സുരക്ഷിതവും സുതാര്യവുമായ പ്ലാറ്റ്ഫോമിലൂടെ പരിശോധിച്ച ഭൂവുടമകളുമായും കർഷകരുമായും കാർഷിക ഭൂമി പാട്ടത്തിന് എടുക്കുകയോ ലിസ്റ്റ് ചെയ്യുകയോ ചെയ്യുക.',
  'services.equipment': 'ഉപകരണ വാടക',
  'services.equipmentBody': 'പരിശോധിച്ച ഉപകരണ ഉടമകളിൽ നിന്ന് ട്രാക്ടറുകൾ, ഹാർവെസ്റ്ററുകൾ, റോട്ടാവേറ്ററുകൾ, സീഡ് ഡ്രില്ലുകൾ, സ്പ്രേയറുകൾ, മറ്റ് അവശ്യ കാർഷിക യന്ത്രങ്ങൾ എന്നിവ നേടുക.',
  'services.labour': 'തൊഴിലാളി, കാർഷിക സേവനങ്ങൾ',
  'services.labourBody': 'വിതയ്ക്കൽ, വിളവെടുപ്പ്, തളിക്കൽ, ജലസേചനം തുടങ്ങിയവയ്ക്ക് വിശ്വസനീയരായ കാർഷിക തൊഴിലാളികളെയും സേവന ദാതാക്കളെയും കണ്ടെത്തുക.',
  'services.produce': 'വിള വിപണി',
  'services.produceBody': 'നിങ്ങളുടെ വിളകൾ പ്രദർശിപ്പിച്ച് പരിശോധിച്ച വാങ്ങുന്നവരുമായി ബന്ധപ്പെട്ട് മത്സരാധിഷ്ഠിത ഓഫറുകളും മികച്ച വിലകളും നേടുക.',
  'services.cta': 'ആരംഭിക്കുക',
  'contact.title': 'ഞങ്ങളെ ബന്ധപ്പെടുക',
  'contact.subtitle': 'നിങ്ങളിൽ നിന്ന് കേൾക്കുന്നതിൽ ഞങ്ങൾക്ക് സന്തോഷമുണ്ട്. പിന്തുണ, പങ്കാളിത്തം അല്ലെങ്കിൽ കൃഷി സംഗമത്തെക്കുറിച്ചുള്ള ഏത് ചോദ്യങ്ങൾക്കും ബന്ധപ്പെടുക.',
