  'auth.optional': 'ഐച്ഛികം',
  'home.hero.title': 'കർഷകർക്കും വാങ്ങുന്നവർക്കും കാർഷിക സേവനങ്ങൾക്കുമായി ഇന്ത്യയുടെ ഡിജിറ്റൽ പാലം',
  'home.hero.subtitle': 'കൃഷി സംഗമം കർഷകരെ പരിശോധിച്ച വാങ്ങുന്നവർ, കാർഷിക യന്ത്രങ്ങൾ, കാർഷിക സേവനങ്ങൾ, സംഭരണ പരിഹാരങ്ങൾ, സാമ്പത്തിക പിന്തുണ, വിദഗ്ദ്ധ മാർഗനിർദേശം എന്നിവയുമായി ബന്ധിപ്പിക്കുന്നു.',
  'home.getStarted': 'ആരംഭിക്കുക',
  'home.exploreServices': 'സേവനങ്ങൾ കാണുക',
  'home.whatIsTitle': 'എന്താണ് കൃഷി സംഗമം?',
  'home.agriSimple': 'കൃഷി ലളിതമാക്കി.',
  'home.whatIsBody': 'കർഷകരെ വിശ്വസനീയമായ ഭൂമി പാട്ടം, യന്ത്രങ്ങൾ, സേവനങ്ങൾ എന്നിവയുമായി ബന്ധിപ്പിക്കുന്ന ഡിജിറ്റൽ പ്ലാറ്റ്ഫോമാണ് കൃഷി സംഗമം.',
