  'home.landLeasing': 'ഭൂമി പാട്ടം',
  'home.landLeasingBody': 'സുതാര്യതയോടെ കാർഷിക ഭൂമി പാട്ടത്തിന് നൽകാൻ ഭൂവുടമകളെയും കർഷകരെയും സുരക്ഷിത പ്ലാറ്റ്ഫോമിൽ ബന്ധിപ്പിക്കുക.',
  'home.equipmentRental': 'യന്ത്രങ്ങൾ വാടകയ്ക്ക്',
  'home.equipmentRentalBody': 'പരിശോധിച്ച ഉടമകളിൽ നിന്ന് ട്രാക്ടർ, ഹാർവെസ്റ്റർ, റോട്ടാവേറ്റർ, സീഡ് ഡ്രിൽ തുടങ്ങിയ ആവശ്യമായ കാർഷിക യന്ത്രങ്ങൾ നേടുക.',
  'home.labourServices': 'കാർഷിക തൊഴിലാളികളും ഫാം സേവനങ്ങളും',
  'home.labourServicesBody': 'വിത്ത് നടൽ, വിളവെടുപ്പ്, തളിക്കൽ, ജലസേചനം തുടങ്ങിയവയ്ക്ക് വിശ്വസനീയരായ കാർഷിക തൊഴിലാളികളെയും സേവന ദാതാക്കളെയും ഒരിടത്ത് കണ്ടെത്തുക.',
  'home.comingSoon': 'ഉടൻ വരുന്നു',
  'home.comingSoonBody': 'കൃഷി സംഗമം ഇന്ത്യയുടെ സമ്പൂർണ്ണ കാർഷിക ആവാസവ്യവസ്ഥയാകാൻ തുടർച്ചയായി വികസിക്കുന്നു. വരാനിരിക്കുന്ന സേവനങ്ങൾ:',
  'home.coming.seeds': 'വിത്തുകൾ, വളങ്ങൾ, കാർഷിക ഇൻപുട്ടുകൾ',
