  'home.coming.finance': 'സാമ്പത്തിക പിന്തുണ, വായ്പകൾ, ഇൻഷുറൻസ്',
  'home.coming.advisory': 'വിദഗ്ദ്ധ കാർഷിക കൺസൾട്ടേഷൻ',
  'home.whyChoose': 'കർഷകർ എന്തുകൊണ്ട് കൃഷി സംഗമം തിരഞ്ഞെടുക്കുന്നു',
  'home.verified': 'പരിശോധിച്ച നെറ്റ്‌വർക്ക്',
  'home.verifiedBody': 'കൂടുതൽ വിശ്വാസത്തിനും സുതാര്യതയ്ക്കുമായി ഓരോ സേവന ദാതാവും പരിശോധനയ്ക്ക് വിധേയരാകുന്നു.',
  'home.saveTime': 'സമയം ലാഭിക്കുക',
  'home.saveTimeBody': 'യന്ത്രങ്ങൾ, തൊഴിലാളികൾ, കാർഷിക സേവനങ്ങൾ എന്നിവ തേടുന്ന ശ്രമം കുറയ്ക്കുക.',
  'home.builtForEvery': 'എല്ലാ കർഷകർക്കും',
  'home.builtForEveryBody': '2 ഏക്കറോ 200 ഏക്കറോ ഉണ്ടെങ്കിലും, എല്ലാ വലുപ്പത്തിലുള്ള ഫാമുകൾക്കും കൃഷി സംഗമം രൂപകൽപ്പന ചെയ്തിരിക്കുന്നു.',
