  'home.sellBody': 'ਪ੍ਰਮਾਣਿਤ ਖਰੀਦਦਾਰਾਂ ਨਾਲ ਸਿੱਧਾ ਜੁੜੋ ਅਤੇ ਸਥਾਨਕ ਮੰਡੀਆਂ ਤੋਂ ਅੱਗੇ ਆਪਣਾ ਬਾਜ਼ਾਰ ਵਧਾਓ। ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਕਿਸਾਨਾਂ ਨੂੰ ਆਪਣੀਆਂ ਫ਼ਸਲਾਂ ਦਿਖਾਉਣ, ਮੁਕਾਬਲੇ ਵਾਲੀਆਂ ਪੇਸ਼ਕਸ਼ਾਂ ਪ੍ਰਾਪਤ ਕਰਨ, ਬਿਹਤਰ ਕੀਮਤਾਂ \'ਤੇ ਗੱਲਬਾਤ ਕਰਨ ਅਤੇ ਵਧੇਰੇ ਪਾਰਦਰਸ਼ਤਾ ਨਾਲ ਵੇਚਣ ਦੇ ਯੋਗ ਬਣਾਉਂਦਾ ਹੈ। ਸਾਡਾ ਪਲੇਟਫਾਰਮ ਵਿਚੋਲਿਆਂ \'ਤੇ ਨਿਰਭਰਤਾ ਘਟਾ ਕੇ ਕਿਸਾਨਾਂ ਦੇ ਮੁਨਾਫ਼ੇ ਨੂੰ ਵੱਧ ਤੋਂ ਵੱਧ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ।',
  'home.sellCta': 'ਫ਼ਸਲ ਵੇਚੋ',
  'home.comingSoonSub': 'ਕ੍ਰਿਸ਼ੀ ਸੰਗਮ ਭਾਰਤ ਦਾ ਸੰਪੂਰਨ ਡਿਜੀਟਲ ਖੇਤੀ ਈਕੋਸਿਸਟਮ ਬਣਨ ਲਈ ਲਗਾਤਾਰ ਵਿਸਤਾਰ ਕਰ ਰਿਹਾ ਹੈ।',
  'home.cs1Title': 'ਬੀਜ, ਖਾਦਾਂ ਅਤੇ ਖੇਤੀ ਇਨਪੁੱਟ',
  'home.cs1Body': 'ਭਰੋਸੇਮੰਦ ਸਪਲਾਇਰਾਂ ਤੋਂ ਪ੍ਰਮਾਣਿਤ ਬੀਜ, ਖਾਦਾਂ, ਕੀਟਨਾਸ਼ਕ ਅਤੇ ਹੋਰ ਜ਼ਰੂਰੀ ਖੇਤੀ ਸਪਲਾਈ ਪ੍ਰਦਾਨ ਕਰੋ।',
  'home.cs2Title': 'ਫ਼ਸਲ ਖਰੀਦ-ਵੇਚ ਬਾਜ਼ਾਰ',
  'home.cs2Body': 'ਇੱਕ ਪਾਰਦਰਸ਼ੀ ਬਾਜ਼ਾਰ ਜਿੱਥੇ ਕਿਸਾਨ ਅਤੇ ਖਰੀਦਦਾਰ ਬਿਹਤਰ ਕੀਮਤਾਂ ਅਤੇ ਵਿਆਪਕ ਬਾਜ਼ਾਰ ਪਹੁੰਚ ਲਈ ਸਿੱਧੇ ਜੁੜ ਸਕਦੇ ਹਨ।',
  'home.cs3Title': 'ਸਟੋਰੇਜ ਅਤੇ ਕੋਲਡ ਚੇਨ ਲੌਜਿਸਟਿਕਸ',
  'home.cs3Body': 'ਵਾਢੀ ਤੋਂ ਬਾਅਦ ਦੇ ਨੁਕਸਾਨ ਨੂੰ ਘਟਾਉਣ ਲਈ ਗੋਦਾਮ, ਕੋਲਡ ਸਟੋਰੇਜ ਅਤੇ ਆਵਾਜਾਈ ਸੇਵਾਵਾਂ ਲੱਭੋ।',
  'home.cs4Title': 'ਵਿੱਤੀ ਸਹਾਇਤਾ, ਕਰਜ਼ੇ ਅਤੇ ਬੀਮਾ',
  'home.cs4Body': 'ਵਿੱਤੀ ਸਹਾਇਤਾ ਅਤੇ ਫ਼ਸਲ ਸੁਰੱਖਿਆ ਲਈ ਬੈਂਕਾਂ, NBFC, ਬੀਮਾ ਪ੍ਰਦਾਤਾਵਾਂ ਅਤੇ ਸਰਕਾਰੀ ਯੋਜਨਾਵਾਂ ਨਾਲ ਜੁੜੋ।',
